 1	/**
 2	 * GUI HTTP Server
 3	 *
 4	 * Standalone Node.js HTTP server that routes requests to API handlers
 5	 * (gui/api.ts) and serves static files from gui/public/. This is a SEPARATE
 6	 * process from the MCP server — stdout logging is allowed and expected.
 7	 *
 8	 * CLI Arguments:
 9	 *   --port <n>           Listen port (default: 3420)
10	 *   --ledger-dir <path>  Ledger root path (handled by resolveLedgerRoot())
11	 */
12	
13	import { createServer } from 'node:http';
14	import type { IncomingMessage, ServerResponse } from 'node:http';
15	import { readFile } from 'node:fs/promises';
16	import { join, extname, dirname, resolve } from 'node:path';
17	import { fileURLToPath } from 'node:url';
18	
19	import { resolveLedgerRoot, resolveProjectDir, ORCHESTRATOR_LOGS_DIR, WORKSPACE_ROOT } from '../src/utils/ledger-root.js';
20	import { SAFE_SLUG_REGEX } from '../src/utils/constants.js';
21	import { captureWorkspaceVersions } from '../src/utils/workspace-versions.js';
22	import type { WorkspaceVersions } from '../src/utils/workspace-versions.js';
23	import { readConfigFromDisk, startConfigWatcher } from '../src/gui/config.js';
24	import { startAutoArchiveTimer } from '../src/gui/auto-archive.js';
25	import {
26	  handleListRunLogs,
27	  handleGetRunLog,
28	} from '../src/gui/handlers/run-log-handlers.js';
29	import {
30	  handleListProjects,
31	  handleGetProject,
32	  handleGetPlanDocument,
33	  handleGetSynthesisDocument,
34	  handleListWorkPackages,
35	  handleGetWorkPackage,
36	  handleDeleteProject,
37	  handleGetInsights,
38	  handleGetConfig,
39	  handleUpdateConfig,
40	  handleResetProject,
41	  handleGetProjectHealth,
42	  handleGetWorkPackageOverview,
43	  handleRenameProject,
44	  handleArchiveProject,
45	  handleUnarchiveProject,
46	  handleMarkProjectComplete,
47	  handleListDialogues,
48	  handleGetDialogueFile,
49	  handleListChunks,
50	  handleGetChunkFile,
51	  handleOrchestratorStart,
52	  handleGetOrchestratorQueue,
53	  handleOrchestratorKill,
54	  handleOrchestratorDismiss,
55	  handleGetRunStatus,
56	  handleGetRunMetadata,
57	  ApiError,
58	} from './api.js';
59	import {
60	  handleListKnowledge,
61	  handleUpdateKnowledge,
62	  handleDeleteKnowledge,
63	  handlePromoteKnowledge,
64	  handleMoveKnowledge,
65	} from './api-knowledge.js';
66	import { renderChunksToMarkdown } from './chunk-renderer.js';
67	
68	// ---------------------------------------------------------------------------
69	// Path resolution (ESM-safe)
70	// ---------------------------------------------------------------------------
71	
72	const __filename = fileURLToPath(import.meta.url);
73	const __dirname = dirname(__filename);
74	
75	const PUBLIC_DIR = join(__dirname, 'public');
76	
77	// ---------------------------------------------------------------------------
78	// CLI argument parsing
79	// ---------------------------------------------------------------------------
80	
81	function getPort(): number {
82	  const args = process.argv;
83	  const idx = args.indexOf('--port');
84	  if (idx !== -1 && idx + 1 < args.length) {
85	    const p = parseInt(args[idx + 1]!, 10);
86	    if (!isNaN(p) && p > 0) return p;
87	  }
88	  return 3420;
89	}
90	
91	// ---------------------------------------------------------------------------
92	// MIME types
93	// ---------------------------------------------------------------------------
94	
95	const MIME_TYPES: Record<string, string> = {
96	  '.html': 'text/html',
97	  '.css': 'text/css',
98	  '.js': 'application/javascript',
99	};

101	// ---------------------------------------------------------------------------
102	// CORS helpers
103	// ---------------------------------------------------------------------------
104	
105	function corsHeaders(port: number): Record<string, string> {
106	  return {
107	    'Access-Control-Allow-Origin': `http://localhost:${port}`,
108	    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
109	    'Access-Control-Allow-Headers': 'Content-Type',
110	  };
111	}
112	
113	// ---------------------------------------------------------------------------
114	// Security headers
115	// ---------------------------------------------------------------------------
116	
117	function securityHeaders(): Record<string, string> {
118	  return {
119	    'X-Content-Type-Options': 'nosniff',
120	    'X-Frame-Options': 'DENY',
121	    'Referrer-Policy': 'strict-origin-when-cross-origin',
122	    'Content-Security-Policy':
123	      "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'",
124	  };
125	}
126	
127	// ---------------------------------------------------------------------------
128	// Response helpers
129	// ---------------------------------------------------------------------------
130	
131	function sendJson(
132	  res: ServerResponse,
133	  status: number,
134	  data: unknown,
135	  port: number
136	): void {
137	  const body = JSON.stringify(data);
138	  res.writeHead(status, {
139	    'Content-Type': 'application/json',
140	    'Content-Length': Buffer.byteLength(body),
141	    ...corsHeaders(port),
142	    ...securityHeaders(),
143	  });
144	  res.end(body);
145	}
146	
147	function sendError(
148	  res: ServerResponse,
149	  status: number,
150	  code: string,
151	  message: string,
152	  port: number
153	): void {
154	  sendJson(res, status, { error: { code, message } }, port);
155	}
156	
157	export function apiErrorToStatus(code: string): number {
158	  switch (code) {
159	    case 'NOT_FOUND':
160	      return 404;
161	    case 'FORBIDDEN':
162	      return 403;
163	    case 'VALIDATION_ERROR':
164	      return 400;
165	    case 'CONFLICT':
166	      return 409;
167	    default:
168	      return 500;
169	  }
170	}
171	
172	// ---------------------------------------------------------------------------
173	// Body reading
174	// ---------------------------------------------------------------------------
175	
176	/** Maximum accepted request body size (1 MiB). */
177	export const MAX_BODY_BYTES = 1_048_576;
178	
179	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
180	export class PayloadTooLargeError extends Error {
181	  constructor() {
182	    super('Payload Too Large');
183	    this.name = 'PayloadTooLargeError';
184	  }
185	}
186	
187	/**
188	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
189	 * {@link MAX_BODY_BYTES} (1 MiB).
190	 *
191	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
192	 *   either via Content-Length header pre-check or streaming byte count).
193	 *   **Callers must catch this error and return a 413 response.**
194	 *
195	 * @param req - The incoming HTTP request.
196	 * @returns The full body string.
197	 */
198	function readBody(req: IncomingMessage): Promise<string> {
199	  return new Promise((resolve, reject) => {
200	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
201	    const declaredLength = req.headers['content-length'];
202	    if (declaredLength !== undefined) {
203	      const n = parseInt(declaredLength, 10);
204	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
205	        req.resume();  // drain body data from socket buffer
206	        reject(new PayloadTooLargeError());
207	        return;
208	      }
209	    }
210	
211	    const chunks: Buffer[] = [];
212	    let totalBytes = 0;
213	    let rejected = false;
214	
215	    req.on('data', (chunk: Buffer) => {
216	      if (rejected) return;
217	      totalBytes += chunk.length;
218	      if (totalBytes > MAX_BODY_BYTES) {
219	        rejected = true;
220	        reject(new PayloadTooLargeError());
221	        // Drain remaining data so the 413 response can be sent cleanly.
222	        req.resume();
223	        return;
224	      }
225	      chunks.push(chunk);
226	    });
227	    req.on('end', () => {
228	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
229	    });
230	    req.on('error', (err) => {
231	      if (!rejected) reject(err);
232	    });
233	  });
234	}
235	
236	/**
237	 * Reads and parses the request body as JSON, enforcing the same size limit as
238	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
239	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
240	 *
241	 * @param req - The incoming HTTP request.
242	 * @returns The parsed JSON value.
243	 */
244	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
245	  const raw = await readBody(req);
246	  try {
247	    return JSON.parse(raw);
248	  } catch {
249	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
250	  }

251	}
252	
253	// ---------------------------------------------------------------------------
254	// Router
255	// ---------------------------------------------------------------------------
256	
257	type RouteHandler = () => Promise<unknown>;
258	
259	// ---------------------------------------------------------------------------
260	// Meta helpers
261	// ---------------------------------------------------------------------------
262	
263	/**
264	 * Guards against path-traversal attacks on URL parameters that are used as
265	 * filesystem path segments.
266	 *
267	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
268	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
269	 * callers receive the same status as a missing project — no information leak.
270	 *
271	 * @param segment - The raw URL parameter value to validate.
272	 */
273	function assertSafeSlug(segment: string): void {
274	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
275	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
276	  }
277	}
278	
279	/**
280	 * Reads the `.meta.json` for a namespaced project at
281	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
282	 *
283	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
284	 * when the field is absent or null.
285	 *
286	 * When the meta file exists but contains malformed JSON, the function still
287	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
288	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
289	 * to URL param '…'`) so operators can detect corrupt meta files during
290	 * troubleshooting. API callers always receive the fallback value in this case.
291	 *
292	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
293	 * indicating that the `{repo}/{slug}` combination is not a known project in
294	 * this ledger. This is the project-existence check for namespaced routes.
295	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
296	 * information-hiding: invalid-input and missing-project cases are
297	 * indistinguishable from the client side.
298	 *
299	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
300	 * before any filesystem access is attempted (defence-in-depth).
301	 */
302	export async function resolveRepoName(
303	  ledgerRoot: string,
304	  repoUrlParam: string,
305	  slugUrlParam: string,
306	): Promise<string> {
307	  assertSafeSlug(repoUrlParam);
308	  assertSafeSlug(slugUrlParam);
309	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
310	  let raw: string;
311	  try {
312	    raw = await readFile(metaPath, 'utf-8');
313	  } catch {
314	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
315	  }
316	  try {
317	    const meta = JSON.parse(raw) as { repository_name?: string | null };
318	    return meta.repository_name ?? repoUrlParam;
319	  } catch {
320	    // Malformed .meta.json — project directory exists, fall back to URL param.
321	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
322	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
323	    return repoUrlParam;
324	  }
325	}
326	
327	/**
328	 * Matches a method + URL path to an API handler.
329	 * Returns a handler thunk or null if no route matches.
330	 */
331	function matchRoute(
332	  method: string,
333	  url: string,
334	  ledgerRoot: string,
335	  orchestratorLogsDir: string
336	): RouteHandler | null {
337	  const [path] = url.split('?') as [string];
338	  const segments = path.split('/').filter(Boolean);
339	
340	  // All API routes must start with 'api'
341	  if (segments[0] !== 'api') return null;
342	
343	  const rest = segments.slice(1);
344	
345	  // Route dispatch note:
346	  // Routes are matched by segment count (rest.length) first, then by segment values.
347	  // Because the dispatcher walks the if-else chain in declaration order, two routes
348	  // that share the same rest.length value are ordered by their position here — the
349	  // first matching branch wins and subsequent branches at the same length are shadowed.
350	  // When adding a new route with the same rest.length as an existing one (e.g. a future
351	  // /:slug/synthesis at length 3 alongside /:slug/plan), make sure the more-specific
352	  // pattern appears BEFORE the catch-all pattern at that length, or it will never match.
353	
354	  // GET /api/insights
355	  if (method === 'GET' && rest.length === 1 && rest[0] === 'insights') {
356	    return () => handleGetInsights(ledgerRoot);
357	  }
358	
359	  // GET /api/orchestrator/queue
360	  if (method === 'GET' && rest.length === 2 && rest[0] === 'orchestrator' && rest[1] === 'queue') {
361	    return () => handleGetOrchestratorQueue(orchestratorLogsDir, ledgerRoot);
362	  }
363	
364	  // GET /api/orchestrator/run-status/:filename
365	  if (method === 'GET' && rest.length === 3 && rest[0] === 'orchestrator' && rest[1] === 'run-status') {
366	    const filename = decodeURIComponent(rest[2]!);
367	    return () => handleGetRunStatus(orchestratorLogsDir, filename);
368	  }
369	
370	  // GET /api/projects
371	  if (method === 'GET' && rest.length === 1 && rest[0] === 'projects') {
372	    const qIdx = url.indexOf('?');
373	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
374	    const sp = new URLSearchParams(qStr);
375	    const params = {
376	      page: sp.get('page') ?? undefined,
377	      limit: sp.get('limit') ?? undefined,
378	      status: sp.get('status') ?? undefined,
379	      search: sp.get('search') ?? undefined,
380	      sort: sp.get('sort') ?? undefined,
381	      dir: sp.get('dir') ?? undefined,
382	      runner: sp.get('runner') ?? undefined,
383	    };
384	    return () => handleListProjects(ledgerRoot, params);
385	  }
386	
387	  // GET /api/projects/:slug/plan
388	  if (
389	    method === 'GET' &&
390	    rest.length === 3 &&
391	    rest[0] === 'projects' &&
392	    rest[2] === 'plan'
393	  ) {
394	    const slug = rest[1]!;
395	    return () => handleGetPlanDocument(ledgerRoot, slug);
396	  }
397	
398	  // GET /api/projects/:slug/synthesis
399	  if (
400	    method === 'GET' &&

401	    rest.length === 3 &&
402	    rest[0] === 'projects' &&
403	    rest[2] === 'synthesis'
404	  ) {
405	    const slug = rest[1]!;
406	    return () => handleGetSynthesisDocument(ledgerRoot, slug);
407	  }
408	
409	  // GET /api/projects/:slug/health
410	  if (
411	    method === 'GET' &&
412	    rest.length === 3 &&
413	    rest[0] === 'projects' &&
414	    rest[2] === 'health'
415	  ) {
416	    const slug = rest[1]!;
417	    return () => handleGetProjectHealth(ledgerRoot, slug);
418	  }
419	
420	  // GET /api/projects/:slug/run-metadata
421	  if (
422	    method === 'GET' &&
423	    rest.length === 3 &&
424	    rest[0] === 'projects' &&
425	    rest[2] === 'run-metadata'
426	  ) {
427	    const slug = rest[1]!;
428	    return () => handleGetRunMetadata(ledgerRoot, slug);
429	  }
430	
431	  // GET /api/projects/:slug
432	  if (method === 'GET' && rest.length === 2 && rest[0] === 'projects') {
433	    const slug = rest[1]!;
434	    return () => handleGetProject(ledgerRoot, slug);
435	  }
436	
