250	    server.listen(0, '127.0.0.1', () => {
251	      const addr = server.address();
252	      if (addr && typeof addr === 'object') {
253	        resolve({ server, baseUrl: `http://127.0.0.1:${addr.port}` });
254	      } else {
255	        reject(new Error('Could not determine server port'));
256	      }
257	    });
258	
259	    server.on('error', reject);
260	  });
261	}
